  if (!years.includes(year)) years.push(year);
  years.sort((a, b) => a - b);

  function showMonth(nextYear: number, nextMonth: number) {
    const next = new Date(nextYear, nextMonth, 1);
    setVisible(next);
    setFocused(next);
  }

